-- Diagnóstico da operação (SOMENTE LEITURA): números agregados, sem nomes nem telefones.
select jsonb_build_object(
 'agora', to_char(now() at time zone 'America/Maceio','DD/MM HH24:MI'),
 'leads_total', (select count(*) from leads),
 'leads_por_etapa', (select jsonb_object_agg(etapa, n) from (select etapa, count(*) n from leads group by 1) x),
 'leads_por_servico', (select jsonb_object_agg(servico, n) from (select servico, count(*) n from leads group by 1) x),
 'leads_por_origem', (select jsonb_object_agg(coalesce(origem,'?'), n) from (select origem, count(*) n from leads group by 1) x),
 'motivos_perda', (select jsonb_object_agg(k, n) from (select etapa || ':' || coalesce(motivo_perda,'sem_motivo') k, count(*) n from leads where etapa in ('perdido','desqualificado') group by 1) x),
 'pag_status', (select jsonb_object_agg(pagamento_status, n) from (select pagamento_status, count(*) n from leads group by 1) x),
 'leads_sem_nome', (select count(*) from leads where nome is null),
 'leads_com_cpf', (select count(*) from leads where cpf_cnpj is not null),
 'eventos_funil', (select jsonb_object_agg(k, n) from (select coalesce(etapa_de,'-') || '>' || etapa_para || ' (' || por || ')' k, count(*) n from eventos_funil group by 1) x),
 'conversas', (select jsonb_build_object('total', count(*), 'assumida_manual', count(*) filter (where assumida_manual), 'aguardando_humano', count(*) filter (where aguardando_humano), 'ia_ativa', count(*) filter (where public.ia_ativa(c)), 'assumida_por', (select jsonb_object_agg(coalesce(assumida_por,'-'), n) from (select assumida_por, count(*) n from conversas where assumida_manual group by 1) y)) from conversas c),
 'handoff_motivos', (select jsonb_object_agg(coalesce(motivo_handoff,'-'), n) from (select motivo_handoff, count(*) n from conversas where motivo_handoff is not null group by 1) x),
 'alertas', (select jsonb_object_agg(k, n) from (select tipo || case when lido then ':lido' else ':nao_lido' end k, count(*) n from alertas group by 1) x),
 'alertas_erro_recentes', (select jsonb_agg(x) from (select to_char(criado_em at time zone 'America/Maceio','DD/MM HH24:MI') q, tipo, left(mensagem, 260) m from alertas where tipo in ('erro','handoff') order by id desc limit 25) x),
 'execucoes', (select jsonb_build_object('total', count(*), 'com_erro', count(*) filter (where erro is not null), 'saida_vazia', count(*) filter (where coalesce(saida,'') = '' and erro is null), 'audio', count(*) filter (where formato = 'audio')) from execucoes_agente),
 'execucoes_erros', (select jsonb_agg(x) from (select to_char(criado_em at time zone 'America/Maceio','DD/MM HH24:MI') q, left(erro, 220) e from execucoes_agente where erro is not null order by id desc limit 12) x),
 'msgs', (select jsonb_object_agg(k, n) from (select autor || '/' || tipo || coalesce('/' || status_envio,'') k, count(*) n from mensagens group by 1) x),
 'msgs_por_dia', (select jsonb_agg(x) from (select to_char(criado_em at time zone 'America/Maceio','DD/MM') d, count(*) filter (where autor='lead') lead, count(*) filter (where autor='ia') ia, count(*) filter (where autor='humano') humano from mensagens group by 1 order by min(criado_em)) x),
 'contratos', (select jsonb_agg(x) from (select servico, modalidade, status, criado_por, count(*) n, sum(valor_total) total, sum(custo_produto) custo from contratos group by 1,2,3,4) x),
 'cobrancas', (select jsonb_agg(x) from (select status, tipo, count(*) n, sum(valor) v, count(*) filter (where erro is not null) com_erro, max(erro) erro from cobrancas group by 1,2) x),
 'comissoes', (select jsonb_agg(x) from (select beneficiario, status, count(*) n, sum(valor) v from comissoes group by 1,2) x),
 'notificacoes', (select jsonb_agg(x) from (select tipo, status, count(*) n from notificacoes group by 1,2) x),
 'asaas_eventos', (select jsonb_agg(x) from (select evento, status, count(*) n from asaas_eventos group by 1,2) x),
 'reunioes', (select jsonb_agg(x) from (select status, count(*) n from reunioes group by 1) x),
 'config', (select jsonb_object_agg(chave, case when chave = 'split_beneficiarios' then (select jsonb_agg(jsonb_build_object('nome', b->>'nome', 'pct', b->>'percentual', 'wallet_ok', length(coalesce(b->>'walletId',''))>10)) from jsonb_array_elements(valor) b) when chave = 'custo_produto' then valor - 'walletId' || jsonb_build_object('wallet_ok', length(coalesce(valor->>'walletId',''))>10) else valor end) from config where chave in ('split_beneficiarios','split_servicos','split_obrigatorio','custo_produto','asaas_ativo','asaas_base_url','asaas_forma_cobranca','asaas_dias_vencimento','planos_limpa_nome','planos_combo','planos_rating','planos_diagnostico','followup_horas','minutos_retorno_humano','sdr_pausado_global','whatsapp_equipe','google_calendar_id','janela_agrupamento_segundos','notif_lembrete_dias','notif_vencida_dias','diagnostico_valor')),
 'config_chaves', (select jsonb_agg(chave order by chave) from config),
 'proposta_paradas', (select jsonb_agg(x) from (select l.etapa, l.servico, l.pagamento_status, to_char(l.proposta_em at time zone 'America/Maceio','DD/MM HH24:MI') proposta, to_char(l.ultima_msg_lead_em at time zone 'America/Maceio','DD/MM HH24:MI') ult_lead, cv.assumida_manual am, cv.aguardando_humano ah, cv.followup_etapa fu, (select m.autor from mensagens m where m.conversa_id = cv.id order by m.id desc limit 1) ult_autor from leads l join conversas cv on cv.lead_id = l.id where l.etapa in ('qualificado','proposta') order by l.proposta_em desc nulls last limit 40) x),
 'sem_resposta', (select jsonb_build_object('lead_falou_por_ultimo_sem_resposta_1h', count(*) filter (where ua = 'lead' and ut < now() - interval '1 hour'), 'desses_com_equipe', count(*) filter (where ua = 'lead' and ut < now() - interval '1 hour' and (am or ah)), 'desses_ia_ativa', count(*) filter (where ua = 'lead' and ut < now() - interval '1 hour' and not am and not ah), 'desses_mais_24h', count(*) filter (where ua = 'lead' and ut < now() - interval '24 hours')) from (select cv.assumida_manual am, cv.aguardando_humano ah, (select m.autor from mensagens m where m.conversa_id = cv.id order by m.id desc limit 1) ua, (select m.criado_em from mensagens m where m.conversa_id = cv.id order by m.id desc limit 1) ut from conversas cv join leads l on l.id = cv.lead_id where l.etapa not in ('perdido','desqualificado','concluido')) z),
 'assumidas_paradas', (select jsonb_build_object('assumidas', count(*), 'sem_msg_humana_24h', count(*) filter (where coalesce(humano_ultima_atividade_em, assumida_em) < now() - interval '24 hours'), 'sem_msg_humana_48h', count(*) filter (where coalesce(humano_ultima_atividade_em, assumida_em) < now() - interval '48 hours')) from conversas cv join leads l on l.id = cv.lead_id where cv.assumida_manual and l.etapa not in ('perdido','desqualificado','concluido','pago')),
 'tempo_1a_resposta_seg', (select jsonb_build_object('mediana', percentile_cont(0.5) within group (order by extract(epoch from primeira_resposta_em - primeira_msg_em)), 'p90', percentile_cont(0.9) within group (order by extract(epoch from primeira_resposta_em - primeira_msg_em)), 'media', avg(extract(epoch from primeira_resposta_em - primeira_msg_em)), 'n', count(*), 'sem_resposta', (select count(*) from leads where primeira_resposta_em is null)) from leads where primeira_resposta_em is not null and primeira_msg_em is not null),
 'pago_sem_contrato', (select count(*) from leads l where l.pagamento_status = 'confirmado' and not exists (select 1 from contratos ct where ct.lead_id = l.id)),
 'contrato_pago_etapa_errada', (select jsonb_agg(x) from (select l.etapa, ct.servico, ct.status, count(*) n from contratos ct join leads l on l.id = ct.lead_id group by 1,2,3) x),
 'etapa_vs_eventos', (select count(*) from leads l where l.etapa <> 'novo' and not exists (select 1 from eventos_funil e where e.lead_id = l.id and e.etapa_para = l.etapa)),
 'kb', (select jsonb_build_object('ativos', count(*) filter (where ativo), 'inativos', count(*) filter (where not ativo)) from kb),
 'usuarios_crm', (select jsonb_agg(jsonb_build_object('papel', papel, 'ativo', ativo)) from crm_usuarios),
 'auditoria_acoes', (select jsonb_object_agg(acao, n) from (select acao, count(*) n from auditoria group by 1) x)
) as d;
